    binary_instruction = ""
    for char in instruction:
        if char == " ":
            binary_instruction += " "
        else:
            binary_instruction += format(ord(char), "08b")
    return binary_instruction

def print_instruction(instruction, times):
    binary_instruction = convert_to_binary(instruction)
    for _ in range(times):
        print(binary_instruction)

instruction = "PRINT 10 TIMES"
print_instruction(instruction, 10)
